import { useId, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ArrowDownToLine, ArrowUpRight, ArrowRight, UsersRound, BriefcaseBusiness, Building2, ClipboardList, Plus, ChevronRight, Check, MapPin, Star, ShieldCheck, Clock3, CalendarDays, Zap, Sparkles } from 'lucide-react';
import { useGetDatabaseQuery, useUpdateEntityMutation } from '../services/adminApi';
import { useAppDispatch } from '../store/hooks';
import { addToast } from '../store/uiSlice';
import { Avatar, Badge, Button } from '../components/atoms';
import { DataState, Modal, PageHeader, Panel } from '../components/molecules';
import { DEMO_TODAY, downloadCsv, formatDate, statusTone } from '../utils';
import type { Candidate, Database } from '../types';

function periodCount(items: { createdAt: string }[], days: number, previous = false) { const end = new Date(DEMO_TODAY); end.setHours(23, 59, 59, 999); if (previous) end.setDate(end.getDate() - days); const start = new Date(end); start.setDate(start.getDate() - days); return items.filter(item => new Date(item.createdAt) > start && new Date(item.createdAt) <= end).length; }
function Sparkline({ pink = false, points }: { pink?: boolean; points: number[] }) { const max = Math.max(...points, 1); const d = points.map((value, index) => `${index * 15},${28 - value / max * 24}`).join(' '); return <svg viewBox="0 0 90 34" className={`metric__sparkline ${pink ? 'metric__sparkline--pink' : ''}`} aria-hidden="true"><polyline points={d} fill="none" stroke="currentColor" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round"/></svg>; }
function TrendChart({ data, days }: { data: Database; days: number }) {
  const gradientId = useId().replace(/:/g, '');
  const [active, setActive] = useState<number | null>(null);
  const points = useMemo(() => Array.from({ length: 7 }, (_, index) => { const reference = new Date(DEMO_TODAY); reference.setHours(23, 59, 59, 999); const end = new Date(reference); end.setDate(end.getDate() - Math.floor((6 - index) * days / 7)); const start = new Date(reference); start.setDate(start.getDate() - Math.floor((7 - index) * days / 7)); const count = (items: { createdAt: string }[]) => items.filter(item => new Date(item.createdAt) > start && new Date(item.createdAt) <= end).length; return { label: formatDate(end.toISOString(), { day: 'numeric', month: 'short' }), candidates: count(data.candidates), applications: count(data.applications) }; }), [data, days]);
  const maximum = Math.max(5, Math.ceil(Math.max(...points.flatMap(point => [point.candidates, point.applications])) / 5) * 5);
  const x = (index: number) => 45 + index * 84;
  const y = (value: number) => 195 - value / maximum * 160;
  const line = (key: 'candidates' | 'applications') => points.map((point, index) => `${index === 0 ? 'M' : 'L'} ${x(index)} ${y(point[key])}`).join(' ');
  const candidatePath = line('candidates');
  return <div className="trend-chart"><svg viewBox="0 0 590 237" role="img" aria-label={`Candidați și aplicări noi din ultimele ${days} zile, în 7 intervale. ${points.map(point => `${point.label}: ${point.candidates} candidați, ${point.applications} aplicări`).join('; ')}`}><defs><linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4965ff" stopOpacity=".16"/><stop offset="100%" stopColor="#4965ff" stopOpacity="0"/></linearGradient></defs>{Array.from({ length: 5 }, (_, index) => <g key={index}><line x1="45" y1={35 + index * 40} x2="549" y2={35 + index * 40} stroke="#eef0f5" strokeDasharray="4 5"/><text x="23" y={39 + index * 40} textAnchor="end" className="trend-chart__label">{maximum - maximum / 4 * index}</text></g>)}<path d={`${candidatePath} L 549 195 L 45 195 Z`} fill={`url(#${gradientId})`}/><path d={line('applications')} fill="none" stroke="#ff79a3" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/><path d={candidatePath} fill="none" stroke="#4965ff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{points.map((point, index) => <g key={point.label}><text x={x(index)} y="222" textAnchor="middle" className="trend-chart__label">{point.label}</text><rect x={x(index) - 27} y="20" width="54" height="177" fill="transparent" onMouseEnter={() => setActive(index)} onMouseLeave={() => setActive(null)}/>{active === index && <><line x1={x(index)} x2={x(index)} y1="30" y2="195" stroke="#4965ff" strokeDasharray="3 4" opacity=".35"/><circle cx={x(index)} cy={y(point.candidates)} r="5" fill="#4965ff" stroke="white" strokeWidth="3"/></>}</g>)}</svg>{active !== null && <div className="trend-chart__tooltip"><strong>{points[active].label}</strong><span>{points[active].candidates} candidați · {points[active].applications} aplicări</span></div>}</div>;
}

export default function DashboardPage() {
  const { data, isLoading, error } = useGetDatabaseQuery();
  const [days, setDays] = useState(7);
  const [profile, setProfile] = useState<Candidate | null>(null);
  const [updateEntity, mutation] = useUpdateEntityMutation();
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  if (!data) return <DataState isLoading={isLoading} error={error}><div/></DataState>;
  const activeJobs = data.jobs.filter(job => job.status === 'Activ');
  const verifiedEmployers = data.employers.filter(employer => employer.status === 'Verificat');
  const pendingJobs = data.jobs.filter(job => job.status === 'În verificare');
  const pendingEmployers = data.employers.filter(employer => employer.status === 'În verificare');
  const recent = [...data.candidates].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 5);
  const upcoming = data.events.filter(event => event.status === 'Programat' && new Date(`${event.date.slice(0, 10)}T${event.time}:00+03:00`) >= DEMO_TODAY).sort((a, b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`))[0];
  const pendingTotal = pendingJobs.length + pendingEmployers.length;
  const metrics = [
    { label: 'Candidați în platformă', value: data.candidates.length, icon: UsersRound, items: data.candidates, suffix: 'candidați noi', color: 'blue', path: '/candidati', spark: [3, 4, 3, 6, 5, 7, 9] },
    { label: 'Joburi active', value: activeJobs.length, icon: BriefcaseBusiness, items: data.jobs, suffix: 'joburi noi', color: 'pink', path: '/joburi', spark: [2, 3, 3, 4, 3, 5, 7] },
    { label: 'Angajatori verificați', value: verifiedEmployers.length, icon: Building2, items: data.employers, suffix: 'angajatori noi', color: 'violet', path: '/angajatori', spark: [2, 4, 3, 4, 6, 5, 7] },
    { label: 'Aplicări primite', value: data.applications.length, icon: ClipboardList, items: data.applications, suffix: 'aplicări noi', color: 'teal', path: '/aplicari', spark: [1, 2, 3, 2, 5, 6, 8] },
  ];
  async function approve(id: string) { try { await updateEntity({ collection: 'jobs', id, changes: { status: 'Activ' } }).unwrap(); dispatch(addToast({ message: 'Jobul a fost aprobat și publicat.' })); } catch { dispatch(addToast({ message: 'Jobul nu a putut fi aprobat.', tone: 'error' })); } }
  return <div className="dashboard">
    <PageHeader eyebrow="ADMINISTRAREA PLATFORMEI JOBBIN" title={`Bine ai revenit, ${data.settings.name.split(' ')[0]}!`} description="Toți candidații, angajatorii și joburile din Jobbin, într-un singur loc." action={<><Button variant="secondary" icon={ArrowDownToLine} onClick={() => downloadCsv('jobbin-rezumat', metrics.map(metric => ({ Indicator: metric.label, Total: metric.value, 'Noi în perioadă': periodCount(metric.items, days) })))}>Exportă raport</Button><Button icon={Plus} onClick={() => navigate('/joburi?create=1')}>Adaugă job</Button></>}/>
    <div className="dashboard__period"><span><CalendarDays size={15}/>{formatDate(DEMO_TODAY.toISOString(), { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</span><div className="segmented" aria-label="Perioada statisticilor"><button className={days === 7 ? 'segmented__active' : ''} onClick={() => setDays(7)} aria-pressed={days === 7}>Ultimele 7 zile</button><button className={days === 30 ? 'segmented__active' : ''} onClick={() => setDays(30)} aria-pressed={days === 30}>Ultimele 30 de zile</button></div></div>
    <div className="dashboard__metrics">{metrics.map(({ label, value, icon: Icon, items, suffix, color, path, spark }) => <Link to={path} className={`metric metric--${color}`} key={label}><div className="metric__heading"><span>{label}</span><span className="metric__icon"><Icon size={19} strokeWidth={1.8}/></span></div><div className="metric__main"><strong>{new Intl.NumberFormat('ro-RO').format(value)}</strong><Sparkline pink={color === 'pink'} points={spark}/></div><div className="metric__footer"><span className="metric__growth"><ArrowUpRight size={13}/>+{periodCount(items, days)}</span><span>{suffix}</span><ChevronRight size={15}/></div></Link>)}</div>
    <div className="dashboard__middle"><Panel className="recruitment-panel"><div className="panel-heading"><div><h2>Activitatea platformei</h2><p>Conexiuni care devin oportunități.</p></div><Link to="/rapoarte" className="text-link">Vezi raportul <ArrowUpRight size={15}/></Link></div><div className="recruitment-panel__summary"><div><strong>{periodCount(data.candidates, days)}</strong><span>candidați noi</span></div><span className="recruitment-panel__summary-divider"/><div><strong>{periodCount(data.applications, days)}</strong><span>aplicări noi</span></div><div className="chart-legend"><span><i/>Candidați</span><span><i/>Aplicări</span></div></div><TrendChart data={data} days={days}/></Panel>
    <Panel className="attention-panel"><div className="panel-heading"><div><span className="attention-panel__eyebrow"><span/> AI CEVA DE REZOLVAT</span><h2>În atenția ta <span className="count-pill">{pendingTotal}</span></h2></div><span className="attention-panel__icon"><ShieldCheck size={23}/></span></div><p className="attention-panel__description">O platformă de încredere începe cu tine.</p><div className="attention-panel__tasks">{pendingJobs.slice(0, 2).map(job => <div className="review-task" key={job.id}><span className="review-task__icon"><BriefcaseBusiness size={17}/></span><div><strong>{job.title}</strong><span>{job.company}</span><small>Job în verificare</small></div><button className="review-task__approve" onClick={() => approve(job.id)} disabled={mutation.isLoading} aria-label={`Aprobă jobul ${job.title}`} title="Aprobă jobul"><Check size={17}/></button></div>)}{pendingEmployers.slice(0, 1).map(employer => <button className="review-task review-task--button" key={employer.id} onClick={() => navigate(`/angajatori?q=${encodeURIComponent(employer.name)}`)}><span className="review-task__icon review-task__icon--pink"><Building2 size={17}/></span><div><strong>{employer.name}</strong><span>{employer.city}</span><small>Angajator nou</small></div><ChevronRight size={17}/></button>)}{pendingTotal === 0 && <div className="all-clear"><ShieldCheck size={35}/><strong>Totul este la zi!</strong><p>Ai verificat toate solicitările.</p></div>}</div><button className="attention-panel__footer" onClick={() => navigate(pendingJobs.length ? '/joburi?status=În verificare' : '/angajatori?status=În verificare')}>Vezi toate solicitările <ArrowRight size={16}/></button></Panel></div>
    <div className="dashboard__bottom"><Panel className="recent-panel"><div className="panel-heading"><div><h2>Candidați recenți</h2><p>Talent nou în comunitatea Jobbin.</p></div><Link to="/candidati" className="text-link">Vezi toți <ArrowRight size={15}/></Link></div><div className="table-scroll"><table className="data-table recent-table"><thead><tr><th>Candidat</th><th>Localitate</th><th>Status</th><th>Notă</th><th><span className="sr-only">Detalii</span></th></tr></thead><tbody>{recent.map(candidate => <tr key={candidate.id}><td><button className="person-cell" onClick={() => setProfile(candidate)}><Avatar name={candidate.name} color={candidate.color}/><span><strong>{candidate.name}</strong><small>{candidate.role}</small></span></button></td><td><span className="location-cell"><MapPin size={13}/>{candidate.city}</span></td><td><Badge tone={statusTone(candidate.status)}>{candidate.status}</Badge></td><td><span className="rating"><Zap size={14}/>{candidate.rating.toFixed(1)}</span></td><td><button className="icon-button" onClick={() => setProfile(candidate)} aria-label={`Vezi profilul ${candidate.name}`}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div><div className="recent-panel__footer"><span>Ultimii {recent.length} candidați înregistrați</span><span className="live-indicator"><span/> Actualizat în timp real</span></div></Panel>
    <Panel className="activity-panel"><div className="panel-heading"><div><h2>Activitate recentă</h2><p>Pulsul comunității tale.</p></div><span className="activity-panel__live"/></div><div className="activity-list">{data.activity.slice(0, 4).map((activity, index) => { const Icon = activity.type === 'candidate' ? UsersRound : activity.type === 'employer' ? Building2 : activity.type === 'job' ? BriefcaseBusiness : Check; return <div className={`activity-item ${index === 0 ? 'activity-item--new' : ''}`} key={activity.id}><span className={`activity-item__icon activity-item__icon--${activity.type}`}><Icon size={15}/></span><div><p>{activity.description}</p><span><Clock3 size={11}/>{formatDate(activity.createdAt, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</span></div></div>; })}</div><Link to="/notificari" className="activity-panel__footer">Toate notificările <ArrowRight size={15}/></Link></Panel></div>
    {upcoming && <div className="upcoming-banner"><span className="upcoming-banner__icon"><CalendarDays size={21}/></span><div><span>URMĂTORUL EVENIMENT</span><strong>{upcoming.title}</strong></div><p>{formatDate(upcoming.date, { day: 'numeric', month: 'long' })} <span>·</span> {upcoming.time} <span>·</span> {upcoming.city}</p><button onClick={() => navigate('/evenimente')}>Vezi calendarul <ArrowUpRight size={17}/></button><Sparkles className="upcoming-banner__decoration" size={70}/></div>}
    <Modal open={!!profile} onClose={() => setProfile(null)} title="Profil candidat">{profile && <div className="candidate-preview"><Avatar name={profile.name} color={profile.color} size="lg"/><h3>{profile.name}</h3><p>{profile.role} · {profile.city}</p><Badge tone={statusTone(profile.status)}>{profile.status}</Badge><div className="candidate-preview__stats"><span><Star size={18}/><strong>{profile.rating.toFixed(1)}</strong> Notă</span><span><strong>{profile.response}%</strong> Răspuns</span><span><strong>{profile.attendance}%</strong> Prezență</span></div><div className="candidate-preview__skills">{profile.skills.map(skill => <span key={skill}>{skill}</span>)}</div><Button variant="secondary" onClick={() => { setProfile(null); navigate(`/candidati?q=${encodeURIComponent(profile.name)}`); }}>Gestionează candidatul <ArrowUpRight size={16}/></Button></div>}</Modal>
  </div>;
}
